<script setup lang="ts">
import {ref,computed,watch} from 'vue';import {Head,Link,router} from '@inertiajs/vue3';
import {LibraryBig,Search,Compass,Save,BookOpen,ChevronDown} from 'lucide-vue-next';import MangaCard from '../components/MangaCard.vue';
interface Shelf{id:number;name:string};interface Item{id:number;manga_id:string;title:string;source_id?:string|null;reading_status:string;notes:string|null;rating:number|null;shelf_id:number|null}
const props=defineProps<{items:Item[];shelves:Shelf[]}>();
const q=ref('');const status=ref('all');const shelf=ref('all');const selected=ref<string|null>(null);
const form=ref({reading_status:'planned',notes:'',rating:'',shelf_id:''});const working=ref(false);
const filtered=computed(()=>props.items.filter(i=>i.title.toLowerCase().includes(q.value.toLowerCase())&&(status.value==='all'||i.reading_status===status.value)&&(shelf.value==='all'||(shelf.value==='none'?i.shelf_id===null:String(i.shelf_id)===shelf.value))));
const opts=[['planned','Por leer'],['reading','Leyendo'],['completed','Completado'],['on_hold','En pausa'],['dropped','Abandonado']];
function edit(item:Item){selected.value=item.manga_id;form.value={reading_status:item.reading_status,notes:item.notes||'',rating:item.rating?String(item.rating):'',shelf_id:item.shelf_id?String(item.shelf_id):''};}
function save(){if(!selected.value)return;working.value=true;router.patch(`/library/${selected.value}`,{reading_status:form.value.reading_status,notes:form.value.notes||null,rating:form.value.rating?Number(form.value.rating):null,shelf_id:form.value.shelf_id?Number(form.value.shelf_id):null},{preserveScroll:true,onFinish:()=>{working.value=false;selected.value=null;}});}
</script>
<template><Head title="Mi biblioteca"/><div class="content"><div class="page-head"><div><div class="eyebrow">✦ Tu colección</div><h1>Mi Biblioteca</h1><p class="lead">Guardá historias, organizá estanterías, puntuá y continuá tus lecturas.</p></div><div class="page-controls"><span class="pill"><LibraryBig :size="15"/> {{items.length}} mangas</span><Link href="/shelves" class="button secondary">Colecciones</Link></div></div>
<div class="panel" style="display:flex;gap:10px;flex-wrap:wrap;margin-bottom:22px"><div class="search-box" style="flex:2"><Search/><input v-model="q" aria-label="Buscar" placeholder="Buscar en mi biblioteca..."/></div><select v-model="status" class="input" style="flex:1;min-width:140px"><option value="all">Todos los estados</option><option v-for="o in opts" :key="o[0]" :value="o[0]">{{o[1]}}</option></select><select v-model="shelf" class="input" style="flex:1;min-width:140px"><option value="all">Todas las colecciones</option><option value="none">Sin colección</option><option v-for="s in shelves" :key="s.id" :value="String(s.id)">{{s.name}}</option></select></div>
<div v-if="filtered.length" class="manga-grid"><div v-for="it in filtered" :key="it.id" class="panel" style="padding:0;overflow:hidden"><MangaCard :id="it.manga_id" :title="it.title" :subtitle="opts.find(o=>o[0]===it.reading_status)?.[1]||'Por leer'"/><div style="padding:12px"><div class="page-controls" style="justify-content:space-between"><span class="tiny">{{it.rating?'★'.repeat(it.rating):'Sin puntuar'}}</span><button class="button secondary" style="padding:7px 10px" @click="selected===it.manga_id?selected=null:edit(it)"><ChevronDown/> Editar</button></div>
<div v-if="selected===it.manga_id" style="display:grid;gap:10px;margin-top:12px"><label class="tiny">Estado<select v-model="form.reading_status" class="input"><option v-for="o in opts" :key="o[0]" :value="o[0]">{{o[1]}}</option></select></label><label class="tiny">Colección<select v-model="form.shelf_id" class="input"><option value="">Sin colección</option><option v-for="s in shelves" :key="s.id" :value="String(s.id)">{{s.name}}</option></select></label><label class="tiny">Puntuación<select v-model="form.rating" class="input"><option value="">Sin puntuación</option><option v-for="i in 5" :key="i" :value="String(i)">{{i}} ★</option></select></label><label class="tiny">Notas<textarea v-model="form.notes" class="input" rows="3" maxlength="3000" placeholder="Tu opinión o notas..."/></label><button class="button primary" :disabled="working" @click="save"><Save/> Guardar cambios</button></div></div></div></div>
<div v-else class="empty"><div class="empty-icon"><LibraryBig/></div><h3>{{items.length?'Sin resultados':'Tu biblioteca está vacía'}}</h3><p>Desde los detalles de un manga, elegí «Añadir a Biblioteca».</p><Link href="/explore" class="button primary"><Compass/> Explorar mangas</Link></div>
</div></template>
